#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

const MIGRATIONS_DIR = path.join(__dirname, 'migrations');

function migrate() {
  // Verify the migrations directory exists
  if (!fs.existsSync(MIGRATIONS_DIR)) {
    console.error(`Error: migrations directory not found at ${MIGRATIONS_DIR}`);
    process.exit(1);
  }

  // Read all entries and filter to only .sql files
  const files = fs
    .readdirSync(MIGRATIONS_DIR)
    .filter((file) => file.toLowerCase().endsWith('.sql'))
    .sort(); // lexicographic sort — works well with timestamped/numbered prefixes

  if (files.length === 0) {
    console.log('No SQL migration files found.');
    return;
  }

  console.log(`Found ${files.length} migration(s) in ${MIGRATIONS_DIR}:`);
  console.log('---');

  files.forEach((file, index) => {
    console.log(`[${index + 1}/${files.length}] Would apply: ${file}`);
  });

  console.log('---');
  console.log('Dry run complete. No migrations were executed.');
}

migrate();

