const fs = require('fs');
const path = require('path');

const MIGRATIONS_DIR = path.join(__dirname, 'migrations');
const ENV_FILE = path.join(__dirname, '.env.test');

/**
 * Minimal .env parser — handles KEY=VALUE lines, comments (#), blank lines,
 * and surrounding single/double quotes on values. No external dependencies.
 */
function loadEnvFile(filePath) {
  if (!fs.existsSync(filePath)) {
    console.error(`Error: env file not found at ${filePath}`);
    process.exit(1);
  }

  const env = {};
  const contents = fs.readFileSync(filePath, 'utf8');

  for (const rawLine of contents.split(/\r?\n/)) {
    const line = rawLine.trim();
    if (!line || line.startsWith('#')) continue;

    const eq = line.indexOf('=');
    if (eq === -1) continue;

    const key = line.slice(0, eq).trim();
    let value = line.slice(eq + 1).trim();

    // Strip surrounding quotes if present
    if (
      (value.startsWith('"') && value.endsWith('"')) ||
      (value.startsWith("'") && value.endsWith("'"))
    ) {
      value = value.slice(1, -1);
    }

    env[key] = value;
  }

  return env;
}

/**
 * Mask credentials in a connection string for safe logging.
 * e.g. postgres://user:secret@host:5432/db -> postgres://user:***@host:5432/db
 */
function redact(connectionString) {
  try {
    const url = new URL(connectionString);
    if (url.password) url.password = '***';
    return url.toString();
  } catch {
    // Not a URL we can parse — fall back to a generic mask
    return '[unparseable connection string]';
  }
}

function migrate() {
  // 1. Resolve DATABASE_URL from .env.test
  const env = loadEnvFile(ENV_FILE);
  const databaseUrl = env.DATABASE_URL;

