#!/usr/bin/env node

/**
 * Database migration script.
 *
 * Reads .sql files from the ./migrations/ directory and logs each filename
 * it would apply, in lexicographic (alphabetical) order. This convention
 * works well when migrations are named with a sortable prefix, e.g.:
 *   001_create_users.sql
 *   002_add_email_index.sql
 *   2024-01-15_add_orders_table.sql
 */

const fs = require('fs');
const path = require('path');

const MIGRATIONS_DIR = path.join(__dirname, 'migrations');

function main() {
  // Verify the migrations directory exists.
  if (!fs.existsSync(MIGRATIONS_DIR)) {
    console.error(`Migrations directory not found: ${MIGRATIONS_DIR}`);
    process.exit(1);
  }

  const stat = fs.statSync(MIGRATIONS_DIR);
  if (!stat.isDirectory()) {
    console.error(`Path is not a directory: ${MIGRATIONS_DIR}`);
    process.exit(1);
  }

  // Read directory entries and keep only .sql files.
  const entries = fs.readdirSync(MIGRATIONS_DIR, { withFileTypes: true });
  const migrations = entries
    .filter((entry) => entry.isFile() && entry.name.toLowerCase().endsWith('.sql'))
    .map((entry) => entry.name)
    .sort(); // Lexicographic sort ensures deterministic ordering.

  if (migrations.length === 0) {
    console.log('No migrations found.');
    return;
  }

  console.log(`Found ${migrations.length} migration(s) in ${MIGRATIONS_DIR}:`);
  migrations.forEach((file, index) => {
    const num = String(index + 1).padStart(3, '0');
    console.log(`  [${num}] would apply: ${file}`);
  });
}

main();

