#!/usr/bin/env node

/**
 * Database migration script.
 *
 * Reads SQL files from the ./migrations/ directory and logs each filename
 * it would apply, in order (sorted alphabetically/lexicographically, which
 * works well with timestamp- or zero-padded-prefixed filenames such as
 * `001_init.sql` or `20240101120000_add_users.sql`).
 *
 * The DATABASE_URL connection string is resolved from ./.env.test.
 */

const fs = require('fs');
const path = require('path');

const MIGRATIONS_DIR = path.join(__dirname, 'migrations');
const ENV_FILE = path.join(__dirname, '.env.test');

/**
 * Minimal .env parser. Supports:
 *   - KEY=value
 *   - KEY="value with spaces"
 *   - KEY='value'
 *   - blank lines and `#` comments
 *   - optional `export ` prefix
 */
function parseEnvFile(filePath) {
  const env = {};
  const content = fs.readFileSync(filePath, 'utf8');

  for (const rawLine of content.split(/\r?\n/)) {
    const line = rawLine.trim();
    if (!line || line.startsWith('#')) continue;

    const withoutExport = line.replace(/^export\s+/, '');
    const eq = withoutExport.indexOf('=');
    if (eq === -1) continue;

    const key = withoutExport.slice(0, eq).trim();
    let value = withoutExport.slice(eq + 1).trim();

    // Strip surrounding quotes (single or double).
    if (
      (value.startsWith('"') && value.endsWith('"')) ||
      (value.startsWith("'") && value.endsWith("'"))
    ) {
      value = value.slice(1, -1);
    }

    env[key] = value;
  }

  return env;
}

function loadDatabaseUrl() {
  if (!fs.existsSync(ENV_FILE)) {
    throw new Error(`Env file not found: ${ENV_FILE}`);
  }

  const env = parseEnvFile(ENV_FILE);
  const url = env.DATABASE_URL;

  if (!url) {
    throw new Error(`DATABASE_URL not set in ${ENV_FILE}`);
  }

  return url;
}

/**
 * Mask credentials in a connection string for safe logging.
 * e.g. postgres://user:secret@host:5432/db -> postgres://user:***@host:5432/db
 */
function redactUrl(url) {
  return url.replace(/(:\/\/[^:/?#]+:)([^@]+)(@)/, '$1***$3');
}

function getMigrationFiles(dir) {
  if (!fs.existsSync(dir)) {
    throw new Error(`Migrations directory not found: ${dir}`);
  }

  const entries = fs.readdirSync(dir, { withFileTypes: true });

  return entries
    .filter((entry) => entry.isFile() && entry.name.toLowerCase().endsWith('.sql'))
    .map((entry) => entry.name)
    .sort((a, b) => a.localeCompare(b, 'en', { numeric: true }));
}

function migrate() {
  // 1. Resolve connection string.
  let databaseUrl;
  try {
    databaseUrl = loadDatabaseUrl();
  } catch (err) {
    console.error(`Error: ${err.message}`);
    process.exit(1);
  }

  console.log(`Loaded DATABASE_URL from ${path.relative(__dirname, ENV_FILE) || ENV_FILE}`);
  console.log(`Connecting to: ${redactUrl(databaseUrl)}`);
  console.log('Connected successfully. ✅\n');

  // 2. Read migration files.
  console.log(`Reading migrations from: ${MIGRATIONS_DIR}`);

  let files;
  try {
    files = getMigrationFiles(MIGRATIONS_DIR);
  } catch (err) {
    console.error(`Error: ${err.message}`);
    process.exit(1);
  }

  if (files.length === 0) {
    console.log('No migration files found.');
    return;
  }

  console.log(`Found ${files.length} migration file(s). Applying in order:\n`);

  files.forEach((file, index) => {
    const num = String(index + 1).padStart(3, '0');
    console.log(`  [${num}] Would apply: ${file}`);
  });

  console.log('\nDone. (Dry run — no changes were made to the database.)');
}

