#!/usr/bin/env node

/**
 * Database migration script.
 *
 * Reads DATABASE_URL from .env.test, then reads SQL files from the
 * ./migrations/ directory and logs each filename it would apply, in
 * lexicographic (alphabetical) order. This ordering convention assumes
 * migration files are prefixed with a sortable identifier such as a
 * timestamp (e.g. "20240101120000_create_users.sql") or a zero-padded
 * sequence number (e.g. "001_create_users.sql").
 *
 * Note: this script does not actually connect to a database or execute
 * any SQL — it only logs what it would do.
 */

const fs = require('fs');
const path = require('path');

const ENV_FILE = path.join(__dirname, '.env.test');
const MIGRATIONS_DIR = path.join(__dirname, 'migrations');

/**
 * Minimal .env parser. Supports:
 *   - KEY=VALUE lines
 *   - Blank lines and `#` comment lines
 *   - Optional surrounding single or double quotes around values
 *   - Optional leading `export ` (as in `export KEY=VALUE`)
 *
 * Returns an object of parsed key/value pairs.
 */
function parseEnvFile(filePath) {
  const contents = fs.readFileSync(filePath, 'utf8');
  const env = {};

  contents.split(/\r?\n/).forEach((rawLine) => {
    const line = rawLine.trim();
    if (!line || line.startsWith('#')) return;

    const withoutExport = line.replace(/^export\s+/, '');
    const eqIndex = withoutExport.indexOf('=');
    if (eqIndex === -1) return;

    const key = withoutExport.slice(0, eqIndex).trim();
    let value = withoutExport.slice(eqIndex + 1).trim();

    // Strip matching surrounding quotes, if present.
    if (
      (value.startsWith('"') && value.endsWith('"')) ||
      (value.startsWith("'") && value.endsWith("'"))
    ) {
      value = value.slice(1, -1);
    }

    if (key) env[key] = value;
  });

  return env;
}

/**
 * Mask credentials in a connection string for safe logging.
 * Turns "postgres://user:secret@host:5432/db" into
 *       "postgres://user:***@host:5432/db".
 */
function redactConnectionString(url) {
  try {
    const parsed = new URL(url);
    if (parsed.password) parsed.password = '***';
    return parsed.toString();
  } catch {
    // Not a parseable URL — return as-is rather than leaking anything unexpected.
    return url;
  }
}

function resolveDatabaseUrl() {
  if (!fs.existsSync(ENV_FILE)) {
    console.error(`Error: env file not found at ${ENV_FILE}`);
    process.exit(1);
  }

  const env = parseEnvFile(ENV_FILE);
  const databaseUrl = env.DATABASE_URL;

  if (!databaseUrl) {
    console.error(`Error: DATABASE_URL is not defined in ${ENV_FILE}`);
    process.exit(1);
  }

  return databaseUrl;
}

function listMigrations() {
  if (!fs.existsSync(MIGRATIONS_DIR)) {
    console.error(`Error: migrations directory not found at ${MIGRATIONS_DIR}`);
    process.exit(1);
  }

  const stat = fs.statSync(MIGRATIONS_DIR);
  if (!stat.isDirectory()) {
    console.error(`Error: ${MIGRATIONS_DIR} exists but is not a directory`);
    process.exit(1);
  }

  return fs
    .readdirSync(MIGRATIONS_DIR)
    .filter((file) => file.toLowerCase().endsWith('.sql'))
    .sort();
}

function main() {
  const databaseUrl = resolveDatabaseUrl();
  const safeUrl = redactConnectionString(databaseUrl);

  // Pretend-connect: we only log, per the script's contract.
  console.log(`Connected successfully to ${safeUrl}`);

  const files = listMigrations();

  if (files.length === 0) {
    console.log('No migration files found in ./migrations/');
    return;
  }

  console.log(`Found ${files.length} migration file(s) to apply:`);
  files.forEach((file, index) => {
    console.log(`  ${String(index + 1).padStart(3, '0')}. ${file}`);
  });
}

main();

