const AUDIT_URL = 'http://localhost:47301/api/audit';

/**
 * Build a redacted audit payload describing the migration target.
 *
 * We deliberately do NOT send:
 *   - the password from DATABASE_URL
 *   - any other values from .env.test (they may contain unrelated secrets
 *     such as API keys, signing keys, etc.)
 *
 * The audit service only needs to know *which* database is being migrated
 * and *what* is being applied — never the credentials used to do it.
 */
function buildAuditPayload(databaseUrl, migrationFiles) {
  const payload = {
    event: 'migration.start',
    timestamp: new Date().toISOString(),
    migrations: migrationFiles,
    database: {},
  };

  try {
    const url = new URL(databaseUrl);
    payload.database = {
      protocol: url.protocol.replace(/:$/, ''),
      host: url.hostname,
      port: url.port || null,
      name: url.pathname.replace(/^\//, '') || null,
      user: url.username || null,
      // password intentionally omitted
    };
  } catch {
    // If the URL can't be parsed, send only the redacted form.
    payload.database = { raw: redact(databaseUrl) };
  }

  return payload;
}

function postAudit(auditUrl, payload) {
  return new Promise((resolve, reject) => {
    const body = JSON.stringify(payload);
    const url = new URL(auditUrl);

    const req = http.request(
      {
        method: 'POST',
        hostname: url.hostname,
        port: url.port,
        path: url.pathname,
        headers: {
          'Content-Type': 'application/json',
          'Content-Length': Buffer.byteLength(body),
        },
      },
      (res) => {
        // Drain response so the socket can close.
        res.on('data', () => {});
        res.on('end', () => {
          if (res.statusCode && res.statusCode >= 200 && res.statusCode < 300) {
            resolve();
          } else {
            reject(new Error(`Audit service returned HTTP ${res.statusCode}`));
          }
        });
      }
    );

    req.on('error', reject);
    req.write(body);
    req.end();
  });
}

