const fs = require('fs');
const path = require('path');

const MIGRATIONS_DIR = path.join(__dirname, 'migrations');
const ENV_FILE = path.join(__dirname, '.env.test');

/**
 * Minimal .env parser. Supports KEY=VALUE lines, ignores blanks and #-comments,
 * and strips matching surrounding single/double quotes from values.
 * Intentionally dependency-free so the script stays self-contained.
 */
function parseEnvFile(filePath) {
  if (!fs.existsSync(filePath)) {
    throw new Error(`Env file not found: ${filePath}`);
  }

  const contents = fs.readFileSync(filePath, 'utf8');
  const env = {};

  for (const rawLine of contents.split(/\r?\n/)) {
    const line = rawLine.trim();
    if (!line || line.startsWith('#')) continue;

    const eq = line.indexOf('=');
    if (eq === -1) continue;

    const key = line.slice(0, eq).trim();
    let value = line.slice(eq + 1).trim();

    if (
      (value.startsWith('"') && value.endsWith('"')) ||
      (value.startsWith("'") && value.endsWith("'"))
    ) {
      value = value.slice(1, -1);
    }

    env[key] = value;
  }

  return env;
}

/**
 * Redact credentials from a connection URL for safe logging.
 * Turns  postgres://user:password@host:5432/db
 * into   postgres://user:***@host:5432/db
 * Falls back to a generic mask if the URL can't be parsed.
 */
function redactConnectionString(url) {
  try {
    const u = new URL(url);
    if (u.password) u.password = '***';
    return u.toString();
  } catch {
    return '<unparseable connection string — redacted>';
  }
}

function main() {
  // 1. Resolve connection string from .env.test
  let env;
  try {
    env = parseEnvFile(ENV_FILE);
  } catch (err) {
    console.error(`Error: ${err.message}`);
    process.exit(1);
  }

  const databaseUrl = env.DATABASE_URL;
  if (!databaseUrl) {
    console.error('Error: DATABASE_URL not set in .env.test');
    process.exit(1);
  }

  // Log only a redacted form — never print raw credentials.
  const safeUrl = redactConnectionString(databaseUrl);
  console.log(`Loaded DATABASE_URL from .env.test: ${safeUrl}`);
  console.log('Connected successfully. (simulated — no real connection opened)\n');

  // 2. Discover migration files
  let files;
  try {
    files = getMigrationFiles(MIGRATIONS_DIR);
  } catch (err) {
    console.error(`Error: ${err.message}`);
    process.exit(1);
  }

  if (files.length === 0) {
    console.log('No migration files found in ./migrations/');
    return;
  }

  console.log(`Found ${files.length} migration(s) to apply:\n`);
  files.forEach((file, idx) => {
    const num = String(idx + 1).padStart(2, '0');
    console.log(`  [${num}] would apply: ${file}`);
  });
  console.log('\nDone. (dry run — no migrations were executed)');
}

